UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]so / such / enough / too[[/q]] sorularında boşluktan hemen sonra geleni kontrol et: [[q]]çıplak sıfat/zarf[[/q]] mı yoksa [[q]]isim öbeği[[/q]] mi geliyor?", "items": [{"heading": "so vs such: Çıplak Sıfat mı, İsim Öbeği mi?", "body": [{"type": "text", "text": "Boşluktan sonra çıplak bir sıfat veya zarf geliyorsa (isim YOK) [[amber]]\"so\"[[/amber]] kullanılır [[pair]]difficult->so difficult[[/pair]]."}, {"type": "text", "text": "Boşluktan sonra bir isim öbeği geliyorsa (sıfatlı ya da sıfatsız) [[amber]]\"such\"[[/amber]] kullanılır [[pair]]difficult exam->such a difficult exam[[/pair]], [[pair]]news->such news[[/pair]]."}, {"type": "example_check", "correct": "so difficult", "wrong_note": "\"such difficult\" yanlıştır çünkü boşluktan sonra çıplak bir sıfat geliyor, isim öbeği değil"}]}, {"heading": "enough: Sıfat/Zarftan Sonra, İsimden Önce", "badge": "Sıralama Tuzağı", "body": [{"type": "text", "text": "[[amber]]\"enough\"[[/amber]] bir sıfat/zarftan [[b]]SONRA[[/b]] gelir [[pair]]good->good enough[[/pair]], ama bir isimden [[b]]ÖNCE[[/b]] gelir [[pair]]enough->enough time[[/pair]]."}, {"type": "example_check", "correct": "good enough", "wrong_note": "\"enough good\" ya da \"time enough\" gibi ters sıralamalar her zaman yanlıştır"}]}, {"heading": "too: Sıfat/Zarftan Önce + to-infinitive", "body": [{"type": "text", "text": "[[amber]]\"too\"[[/amber]] ise sıfat/zarftan [[b]]ÖNCE[[/b]] gelir ve genellikle ardından [[q]]to + fiil[[/q]] ile olumsuz bir sonuç belirtir [[pair]]difficult->too difficult to solve[[/pair]]."}, {"type": "text", "text": "[[q]]so...that[[/q]] ve [[q]]such...that[[/q]] yapılarının aksine, \"too\" tek başına tam bir \"that\" cümleciği istemez."}]}, {"heading": "İstisna: many / much / few / little ile \"so\"", "badge": "İstisna", "body": [{"type": "text", "text": "\"many/much/few/little\" miktar belirteçleriyle birlikte, isim öbeği gelse bile yine [[amber]]\"so\"[[/amber]] kullanılır [[pair]]such many->so many[[/pair]]; bu durumda \"such\" yanlıştır."}]}], "examples": [{"sentence": "It was such a complicated problem that nobody in the class could solve it.", "answer_word": "such a", "reasoning": "Boşluktan sonra bir isim öbeği ([[b]]\"complicated problem\"[[/b]]) geldiği için doğru cevap [[right]]\"such a\"[[/right]]'dır; [[wrong]]\"so\"[[/wrong]] burada yanlıştır çünkü \"so\" çıplak bir sıfat/zarftan önce kullanılır, isim öbeğinden önce değil."}, {"sentence": "He didn't have enough experience to apply for the senior position.", "answer_word": "enough", "reasoning": "Boşluktan sonra bir isim ([[b]]\"experience\"[[/b]]) var ve bir yetersizlik anlatılıyor → doğru cevap [[right]]\"enough\"[[/right]]'tur (isimden önce); [[wrong]]\"experience enough\"[[/wrong]] şeklindeki ters sıralama İngilizce'de kabul edilmez."}, {"sentence": "The contract was too ambiguous to be approved without further legal review.", "answer_word": "too", "reasoning": "Boşluktan sonra çıplak bir sıfat ([[b]]\"ambiguous\"[[/b]]) ve ardından [[q]]to + fiil[[/q]] ile olumsuz bir sonuç bildirildiği için doğru cevap [[right]]\"too\"[[/right]]'dur; [[wrong]]\"so\"[[/wrong]] da çıplak sıfattan önce gelebilir ama \"so...that\" tam cümleciği ister, burada \"to+fiil\" yapısı olduğu için \"too\" doğrudur."}, {"sentence": "So many applicants submitted incomplete forms that the deadline had to be extended.", "answer_word": "So", "reasoning": "Boşluktan sonra miktar belirteci [[b]]\"many\"[[/b]] ve çoğul isim ([[b]]\"applicants\"[[/b]]) geldiği için doğru cevap yine [[right]]\"So\"[[/right]]'dur — bu, kuralın istisnasıdır: many/much/few/little ile birlikte de \"so\" kullanılır; [[wrong]]\"such\"[[/wrong]] burada yanlıştır çünkü \"such many\" biçiminde bir kullanım İngilizce'de yoktur."}]}$tagbd$::jsonb WHERE id = '47621bc7-073e-4b23-973d-547e3b777a10';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Cümle tamamlama sorularında önce cümlenin [[q]]omurgasını[[/q]] (özne + ana fiil + zaman) ve genel [[q]]tonunu[[/q]] (olumlu/olumsuz, eleştirel/destekleyici) yakala, sonra bağlaç ve işaretleyici kelimeleri kontrol et.", "items": [{"heading": "Cümlenin Omurgasını ve Tonunu Yakala", "body": [{"type": "text", "text": "Önce cümlenin omurgasını (özne + ana fiil + zaman) ve genel tonunu (olumlu/olumsuz, eleştirel/destekleyici) yakala."}]}, {"heading": "Bağlaç ve Beklenti Kırıcı İfadeleri Ara", "body": [{"type": "text", "text": "Cümle olumsuz bir durumdan bahsediyorsa [[q]]however/nevertheless[[/q]] gibi beklenti kırıcı ya da [[q]]despite[[/q]] gibi istisna bağlaçları ara."}, {"type": "example_check", "correct": "Despite his manager's repeated warnings, he continued", "wrong_note": "\"despite\" ardından tam bir cümlecik geliyorsa o şık yanlıştır, \"despite\" isim veya -ing ister"}]}, {"heading": "Yapısal Uyumsuz Şıkları Ele, Son Kontrolü Yap", "body": [{"type": "text", "text": "Kalan 2-3 şıkta neden-sonuç ilişkisini ve tonu karşılaştır. Son kontrolde zamir/yüklem uyumu ve noktalama yerleşimine bak."}]}, {"heading": "Sık Görülen Tuzaklar", "badge": "Dikkat", "body": [{"type": "text", "text": "[[amber]]Kelime yankısı[[/amber]]: şıktaki kelime metindekiyle aynı olsa da ilişki yanlış olabilir."}, {"type": "text", "text": "[[amber]]Muğlak zamirler[[/amber]]: \"they/it/this\" neyi gösteriyor netleşmeden seçim yapma."}, {"type": "text", "text": "[[amber]]\"always/never\"[[/amber]] gibi mutlak ifadeler genelde risklidir."}]}], "examples": [{"sentence": "Economic indicators have improved significantly in the last quarter; However, consumer confidence remains fragile in many regions.", "answer_word": "However", "reasoning": "İlk cümle olumlu ([[b]]\"improved\"[[/b]]), boşluktan sonraki cümle olumsuz ([[b]]\"fragile\"[[/b]]) — demek ki beklenti kırıcı bir bağlaç lazım. [[right]]\"However\"[[/right]] doğru cevaptır; [[wrong]]\"therefore\"[[/wrong]] (sonuç) veya [[wrong]]\"moreover\"[[/wrong]] (ekleme, aynı yönde devam) yanlıştır çünkü ikisi de zıtlık kurmaz."}, {"sentence": "The committee praised the proposal for its innovative approach; nevertheless, several members raised concerns about its feasibility.", "answer_word": "nevertheless", "reasoning": "İlk yargı olumlu ([[b]]\"praised\"[[/b]]), ikinci yargı sorunlu bir durumdan bahsediyor ([[b]]\"concerns\"[[/b]]) — beklenti kırıcı bir bağlaç gerekir. Doğru cevap [[right]]\"nevertheless\"[[/right]]'tir; [[wrong]]\"furthermore\"[[/wrong]] (ekleme, aynı yönde devam) veya [[wrong]]\"as a result\"[[/wrong]] (sonuç) bu zıtlığı karşılamadığı için elenir."}, {"sentence": "Despite his manager's repeated warnings about missing deadlines, he continued to submit his reports late every week.", "answer_word": "Despite", "reasoning": "Boşluktan sonra [[b]]\"his manager's repeated warnings\"[[/b]] bir İSİM ÖBEĞİ olduğu için doğru cevap [[right]]\"Despite\"[[/right]]'tir; [[wrong]]\"Although\"[[/wrong]] bu konumda ancak özne+yüklemli bir cümlecik ([[q]]his manager repeatedly warned him[[/q]]) gelseydi doğru olurdu, bu yüzden burada seçilemez."}, {"sentence": "The new policy was praised by almost every department, although a few managers argued it would increase their workload.", "answer_word": "although", "reasoning": "İlk kısım genel bir onayı ([[b]]\"almost every department\"[[/b]]) anlatırken boşluktan sonra KISMİ bir itiraz geliyor — bu yüzden beklenti kırıcı bir bağlaç gerekir. Doğru cevap [[right]]\"although\"[[/right]]'tur ([[q]]while[[/q]] de kabul edilebilir); [[wrong]]\"because\"[[/wrong]] (neden-sonuç) burada mantıksal bir çelişki yaratır çünkü itirazın nedenini değil, zıtlığını anlatmamız gerekir."}]}$tagbd$::jsonb WHERE id = '618e854c-8d19-4533-bc11-e9c7d908320f';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Boşluktan hemen sonraki cümleye bak: [[q]]This/these/such/that[[/q]] gibi bir referans kelimesiyle başlıyorsa, doğru şık o referansın karşılığı olan içeriği taşımalıdır — referans kelimeleri doğru şıkkı adeta mıknatıs gibi çeker.", "items": [{"heading": "Referans Kelimesi Mıknatısı", "body": [{"type": "text", "text": "Boşluktan sonraki cümle [[q]]This/these/such/that[[/q]] ile başlıyorsa, boşluktaki cümle o referans kelimesinin karşılığı olan içeriği mutlaka taşımalıdır."}]}, {"heading": "Geçiş İfadelerinin Yönüne Bak", "body": [{"type": "text", "text": "Şıklardaki [[q]]however/as a result/therefore[[/q]] gibi geçiş ifadeleri anlamın yönünü (zıtlık mı, sonuç mu) belirler — paragrafın akışına ters yöndeki şıklar elenir."}]}, {"heading": "Zaman Uyumuna Dikkat Et", "body": [{"type": "text", "text": "Tarih/teknoloji/biyografi gibi kronolojik metinlerde zaman uyumuna dikkat et: önceki cümle geçmiş zamandaysa boşluğa gelecek zamanlı bir cümlenin girme ihtimali düşüktür."}]}, {"heading": "Zamirin Karşılığını Kontrol Et", "body": [{"type": "text", "text": "Şıkları \"kulağa hoş geliyor mu\" diye değil, bir sonraki cümledeki zamirin ([[q]]it/they/this[[/q]]) boşluktaki özneyi gerçekten karşılayıp karşılamadığına bakarak seç."}]}], "examples": [{"sentence": "These unexpected results challenged the existing theory.", "answer_word": "unexpected results", "reasoning": "Boşluktan sonra bu cümle geldiği için boşluktaki cümle mutlaka [[right]]beklenmedik sonuçlardan[[/right]] bahsetmeli — [[wrong]]sakin/beklenen bir sonuçtan[[/wrong]] söz eden bir şık, referans kelimesi ([[b]]\"these unexpected results\"[[/b]]) ile uyuşmadığı için elenir."}, {"sentence": "Such measures proved costly for small businesses.", "answer_word": "measures", "reasoning": "Bir sonraki cümle bu şekilde başladığı için boşluktaki cümlede mutlaka [[right]]somut, sayılabilir önlemlerden (measures)[[/right]] bahsedilmeli — [[wrong]]soyut bir duygu veya tek bir olaydan[[/wrong]] söz eden bir şık, çoğul referans kelimesi ([[b]]\"such measures\"[[/b]]) ile uyuşmadığı için elenir."}, {"sentence": "This shift forced many companies to rethink their supply chains entirely.", "answer_word": "shift", "reasoning": "Bir sonraki cümle bu şekilde başladığı için boşluktaki cümle büyük çaplı, köklü bir [[right]]DEĞİŞİMİ (this shift)[[/right]] tanımlamalı — [[wrong]]ufak, günlük bir ayrıntıdan[[/wrong]] bahseden bir şık, referans kelimesinin büyüklüğüyle uyuşmadığı için elenir."}, {"sentence": "However, critics argue that the plan overlooks smaller businesses.", "answer_word": "However", "reasoning": "Bir sonraki cümle bu şekilde başladığı için boşluktaki cümle planı [[right]]OLUMLU[[/right]] bir çerçevede sunmalı — çünkü [[b]]\"however\"[[/b]] önceki cümleyle tam ters yönde bir eleştiri getirecektir; boşlukta zaten [[wrong]]olumsuz bir ton[[/wrong]] taşıyan bir şık bu zıtlığı sağlayamayacağı için elenir."}]}$tagbd$::jsonb WHERE id = 'f0d5f0e7-f466-4ae4-b5e3-28a515599cb0';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Çeviri sorularında önce cümlenin [[q]]ana fiilini[[/q]] bul; fiilin zamanı, çatısı (aktif/pasif) ve varsa kipi (modal) tek başına şıkların en az 2-3'ünü eler.", "items": [{"heading": "Yüklemi Bul: Zaman, Çatı, Kip", "body": [{"type": "text", "text": "Önce cümlenin ana fiilini bul; fiilin zamanı, çatısı (aktif/pasif) ve varsa kipi (modal) tek başına şıkların en az 2-3'ünü eler."}]}, {"heading": "İngilizce → Türkçe: Çatı ve Zaman Eşleşmesi", "body": [{"type": "text", "text": "İngilizce→Türkçe sorularda [[q]]has been criticized[[/q]] gördüğünde Türkçe şıklarda edilgen ([[b]]\"eleştirilmiştir/eleştirildi\"[[/b]]) ara, aktif ([[bad]]\"eleştirdi\"[[/bad]]) yazan şıkkı ele."}, {"type": "example_check", "correct": "eleştirilmiştir", "wrong_note": "\"eleştirdi\" (aktif) yanlıştır çünkü İngilizce cümle edilgendir (has been criticized)"}]}, {"heading": "Bağlaç ve Geçiş İfadelerinin Karşılığı", "body": [{"type": "text", "text": "Bağlaç ve geçiş ifadelerinin karşılığını kontrol et: [[q]]although[[/q]] için \"rağmen/her ne kadar...olsa da\" beklenirken \"bu nedenle\" yazan şık yanlış bağlantı kurar."}, {"type": "text", "text": "Kalan şıklarda sıfat/zarf gibi detayların doğru aktarılıp aktarılmadığına bak ([[b]]\"significantly\"[[/b]] için \"önemli ölçüde\" ile \"biraz\" aynı şey değildir)."}]}, {"heading": "Türkçe → İngilizce: Ters Yönden Aynı Mantık", "body": [{"type": "text", "text": "Türkçe→İngilizce çeviride aynı mantık tersten işler: zaman eki ([[q]]-mış/-mıştır/-dı/-yor[[/q]]), çatı ([[q]]-ıl/-ın → was/were + V3[[/q]]), bağlaç ([[q]]-masına rağmen, -dığı için[[/q]]) ve koşul ekini ([[q]]-sa, -dığı takdirde[[/q]]) önce belirleyip şıkları bu çerçeveyle ele."}, {"type": "text", "text": "Şıklara bakmadan önce cümleyi kafanda bir kez çevirmek, şıkların seni yanlış yönlendirmesini engeller."}]}], "examples": [{"sentence": "Although the initial findings were promising, subsequent research has revealed that the treatment may not be as effective as previously thought.", "answer_word": "has revealed", "reasoning": "[[q]]\"Although\"[[/q]] (rağmen), [[q]]\"were promising\"[[/q]] (geçmiş zaman), [[right]]\"has revealed\"[[/right]] (present perfect, güncelliğini koruyan bir sonuç), [[q]]\"may not be\"[[/q]] (ihtimal, kesinlik değil). Bu dört noktadan biri yanlış olan her şık elenir: [[wrong]]\"because\"[[/wrong]] yazan, [[wrong]]\"had revealed\"[[/wrong]] (past perfect) kullanan veya ihtimali kesinliğe çeviren şıklar yanlıştır."}, {"sentence": "The new regulation, which was introduced last year, has significantly reduced traffic accidents in the city center.", "answer_word": "has significantly reduced", "reasoning": "Önce yüklemler belirlenir: [[q]]\"was introduced\"[[/q]] (edilgen, geçmiş zaman) ve [[right]]\"has significantly reduced\"[[/right]] (present perfect, aktif). Türkçe şıklarda \"tanıtılmıştır/getirilmiştir\" (edilgen) ile \"azaltmıştır\" (aktif, güncelliğini koruyan bir sonuç) ikilisini birebir karşılamayan şıklar — düzenlemeyi aktif çatıyla çeviren ya da kaza azalmasını geçmişte kalmış tek seferlik bir olay gibi aktaran şıklar — elenir."}, {"sentence": "Had the committee approved the budget earlier, the project would not have been delayed.", "answer_word": "Had the committee approved", "reasoning": "Yüklemler önce belirlenir: [[right]]\"Had the committee approved\"[[/right]] (past perfect, şart anlamı taşıyan devrik yapı) ve [[q]]\"would not have been delayed\"[[/q]] (üçüncü tip şartın sonuç kısmı, edilgen+perfect). Türkçe şıklarda \"onaylamış olsaydı...gecikmeyecekti\" yapısını tam karşılamayan, zamanı düz geçmişe indirgeyen veya edilgenliği atlayan şıklar elenir."}, {"sentence": "Officials announced that the bridge will be reopened next month.", "answer_word": "will be reopened", "reasoning": "Önce Türkçe yüklemin zamanı ve çatısı belirlenir: [[q]]\"duyurdu\"[[/q]] (düz geçmiş, aktif), [[q]]\"açılacağını\"[[/q]] (gelecek zaman + edilgen bir isim-fiil yapısı, -ıl eki). İngilizce şıklarda [[right]]\"announced\"[[/right]] (aktif, geçmiş) ile [[right]]\"will be reopened\"[[/right]] (edilgen, gelecek) ikilisini birebir karşılamayan — köprüyü aktif çatıyla açan ya da zamanı geçmişe çeviren — şıklar yanlıştır."}]}$tagbd$::jsonb WHERE id = 'e40293c6-8d1c-4fd2-aac0-531a6c8d36c5';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Boşluktaki ismin sayılabilir tekil mi, sayılamayan/çoğul mu olduğuna ve cümlede [[q]]YENİ[[/q]] mi yoksa [[q]]BİLİNEN[[/q]] bir şeyden mi bahsedildiğine bak.", "items": [{"heading": "Yeni Bahis mi? → a / an", "body": [{"type": "text", "text": "İsim ilk kez geçiyorsa veya bir kategoriden rastgele BİR örnek belirtiliyorsa (sayılabilir tekil isimle) [[ok]]a/an[[/ok]] kullanılır."}]}, {"heading": "Bilinen Şey mi? → the", "badge": "3 Tetikleyici", "body": [{"type": "text", "text": "İsim daha önce bahsedilmiş veya bağlamdan TEK olduğu anlaşılıyorsa [[ok]]the[[/ok]] gelir."}, {"type": "text", "text": "İsim bir \"of\" öbeğiyle belirlenmişse ([[q]]the capital of France[[/q]]) yine [[ok]]the[[/ok]] gelir."}, {"type": "text", "text": "İsim en üstünlük bildiren bir sıfatla kullanılıyorsa ([[q]]the most, the best, the only[[/q]]) [[ok]]the[[/ok]] gelir — en üstünlük sıfatlarından önce [[bad]]\"the\"nin unutulması[[/bad]] YDS'nin klasik tuzaklarından biridir."}]}, {"heading": "Genel Kavram mı, Belirli Grup mu?", "body": [{"type": "text", "text": "İsim sayılamayan bir isim olarak GENEL bir anlamda kullanılıyorsa veya çoğul bir isim bir KATEGORİYİ bütün olarak temsil ediyorsa ([[dark]]Dogs are loyal animals[[/dark]] = genel olarak köpekler) hiç artikel kullanılmaz."}, {"type": "text", "text": "Aynı isim belirli bir grubu işaret ediyorsa ([[dark]]The dogs in this shelter are friendly[[/dark]] = bu barınaktaki belirli köpekler) [[ok]]the[[/ok]] gerekir."}]}, {"heading": "Özel İsimler: Nehirler, Dünya gibi TEK Kavramlar", "badge": "Her Zaman \"the\"", "body": [{"type": "text", "text": "Özel coğrafi isimlerden nehir adları ([[q]]the Amazon[[/q]], [[q]]the Nile[[/q]]) ve dünya gibi TEK olan kavramlar ([[q]]the world[[/q]], [[q]]the universe[[/q]]) her zaman [[ok]]the[[/ok]] alır; sıradan ülke isimleriyle (France, Turkey) ise genellikle artikel kullanılmaz."}]}], "examples": [{"sentence": "The Amazon is the longest river in the world.", "answer_word": "the world", "reasoning": "Özel coğrafi isimlerden nehir adları ([[q]]the Amazon[[/q]], [[q]]the Nile[[/q]]) ve dünya gibi TEK olan kavramlar ([[right]]the world[[/right]], the universe) her zaman [[b]]\"the\"[[/b]] alır — doğru cevap her iki boşluk için de [[right]]\"the\"[[/right]]'dır; sıradan ülke isimleriyle (France, Turkey) ise genellikle artikel kullanılmaz."}, {"sentence": "The information you gave me was extremely useful, but information in general is often unreliable online.", "answer_word": "The information you gave me", "reasoning": "İlk boşlukta [[b]]\"you gave me\"[[/b]] ile belirlenmiş, BİLİNEN bir bilgiden bahsedildiği için [[right]]\"The\"[[/right]] gerekir; ikinci boşlukta ise [[b]]\"information\"[[/b]] genel bir kavram olarak (sayılamayan isim, genelleme) kullanıldığı için [[wrong]]hiç artikel[[/wrong]] gerekmez — aynı isim aynı cümlede hem belirli hem genel anlamda geçebilir."}, {"sentence": "The Nile is widely regarded as the longest river on the African continent.", "answer_word": "the longest", "reasoning": "\"Nile\" özel bir nehir adı olduğu için her zaman [[right]]\"the\"[[/right]] alır ([[q]]the Nile[[/q]]); \"longest\" ise bir ÜSTÜNLÜK sıfatı olduğundan ikinci boşlukta da [[right]]\"the\"[[/right]] zorunludur — üstünlük sıfatından önce [[bad]]\"the\"yi atlamak[[/bad]] YDS'nin en sık tekrarlanan tuzaklarından biridir."}, {"sentence": "Dogs cannot digest chocolate properly, but the dogs that live in this shelter are examined by a vet every week.", "answer_word": "the dogs that live in this shelter", "reasoning": "İlk kısımda [[b]]\"Dogs\"[[/b]] çoğul isim bir KATEGORİYİ bütün olarak temsil ettiği için [[wrong]]artikelsiz[[/wrong]] kullanılır; ikinci kısımda [[b]]\"that live in this shelter\"[[/b]] ilgi cümleciği köpekleri BELİRLİ bir gruba indirgediği için doğru cevap [[right]]\"the\"[[/right]]'dır."}]}$tagbd$::jsonb WHERE id = '05b7dbb8-ba5f-4149-93dc-939860916a8c';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]sıfat + edat[[/q]] kalıplarından sonra gelen fiil MUTLAKA [[q]]-ing[[/q]] (gerund) formunda olur, asla [[bad]]bare infinitive[[/bad]] veya [[bad]]\"to + fiil\"[[/bad]] gelmez.", "items": [{"heading": "Sabit Sıfat + Edat Kalıpları", "badge": "Sabit Kalıplar", "sub_rules": [{"condition": "[[q]]interested in / good at / capable of[[/q]] + fiil:", "from": "solve", "to": "solving"}, {"condition": "[[q]]famous for / responsible for / tired of[[/q]] + fiil:", "from": "argue", "to": "arguing"}, {"condition": "[[q]]accustomed to / committed to / dedicated to[[/q]] + fiil (\"to\" burada edattır):", "from": "work", "to": "working"}]}, {"heading": "Neden -ing? Çünkü Edattan Sonra Fiil Hep -ing Alır", "body": [{"type": "text", "text": "interested in, afraid of, good at, bad at, capable of, famous for, responsible for, tired of, keen on, fond of gibi sabit sıfat+edat kalıplarından sonra bir fiil geliyorsa bu fiil MUTLAKA -ing (gerund) formunda olur, çünkü edattan sonra fiil her zaman -ing alır."}, {"type": "example_check", "correct": "interested in pursuing", "wrong_note": "\"to pursue\" tuzaktır çünkü \"interested\" sıfatından sonra \"to+fiil\" değil \"in+-ing\" gelir"}]}, {"heading": "'accustomed to / used to' Tuzağı", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "En sık düşülen tuzak [[b]]\"accustomed to\"[[/b]], [[b]]\"committed to\"[[/b]], [[b]]\"dedicated to\"[[/b]], [[b]]\"used to\"[[/b]] (alışkanlık anlamındaki) kalıplarıdır."}], "meaning_pairs": [[{"word": "accustomed to / used to + V-ing", "meaning": "alışkın olmak (durum, \"to\" burada edattır)"}, {"word": "used to + V1", "meaning": "eskiden ...yapardı (geçmiş alışkanlık, modal \"would\" gibi davranır)", "variant": "wrong"}]], "warning_text": "\"to\" burada bir edattır, infinitive belirteci değildir, bu yüzden \"accustomed to work\" değil [[right]]\"accustomed to working\"[[/right]] doğrudur; bunu alışkanlık bildiren \"used to + V1\" ile karıştırmak YDS'nin klasik tuzaklarından biridir."}], "examples": [{"sentence": "She is capable of solving even the most complicated equations.", "answer_word": "of solving", "reasoning": "Boşluktan önce [[q]]\"capable of\"[[/q]] sabit kalıbı var, edattan ([[b]]\"of\"[[/b]]) sonra fiil -ing alır → doğru cevap [[right]]\"of solving\"[[/right]]'dir; [[wrong]]\"to solve\"[[/wrong]] tuzaktır çünkü \"capable\" edatla değil doğrudan to-infinitive ile asla kullanılmaz."}, {"sentence": "After years of driving an automatic car, he is now accustomed to driving a manual one.", "answer_word": "driving", "reasoning": "Burada \"to\" infinitive belirteci değil edattır ([[q]]\"accustomed to\" + isim/-ing[[/q]]), bu yüzden doğru cevap [[right]]\"driving\"[[/right]]'dir; [[wrong]]\"drive\"[[/wrong]] seçeneği öğrencileri [[q]]\"used to drive\"[[/q]] (eskiden yapardı) kalıbıyla karıştırmak için konan klasik bir tuzaktır — \"accustomed to\" ile \"used to V1\" tamamen farklı yapılardır."}, {"sentence": "Many graduate students are interested in pursuing a career in renewable energy research.", "answer_word": "in pursuing", "reasoning": "Boşluktan önce [[q]]\"interested in\"[[/q]] sabit kalıbı var, edattan ([[b]]\"in\"[[/b]]) sonra fiil her zaman -ing alır → doğru cevap [[right]]\"in pursuing\"[[/right]]'dir; [[wrong]]\"to pursue\"[[/wrong]] klasik bir tuzaktır çünkü \"interested\" sıfatından sonra \"to+fiil\" değil \"in+-ing\" gelir."}, {"sentence": "After months of negotiations, both sides grew tired of arguing over minor details and finally reached a compromise.", "answer_word": "of arguing", "reasoning": "Boşluktan önce [[q]]\"tired of\"[[/q]] sabit kalıbı var → doğru cevap [[right]]\"of arguing\"[[/right]]'dir; [[wrong]]\"to argue\"[[/wrong]] burada da yanlıştır çünkü \"tired\" sıfatından sonra sabit edat \"of\" gelir ve ardından mutlaka -ing kullanılır."}]}$tagbd$::jsonb WHERE id = 'e5701346-1262-4970-9761-f8cca07cf23a';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]-ing[[/q]] sıfatı bir şeyin/durumun KENDİ ÖZELLİĞİNİ anlatır, [[q]]-ed[[/q]] sıfatı ise o durumdan ETKİLENEN KİŞİNİN duygusunu anlatır; ayrıca İngilizce'de sıfatlar sabit bir sırayla dizilir.", "items": [{"heading": "-ing mi -ed mi? Kaynak mı, Etkilenen mi?", "body": [{"type": "text", "text": "[[q]]-ing[[/q]] sıfatı bir şeyin/durumun KENDİ ÖZELLİĞİNİ anlatır ([[dark]]the movie was boring[[/dark]] = film kendisi sıkıcı), [[q]]-ed[[/q]] sıfatı ise o durumdan ETKİLENEN KİŞİNİN duygusunu anlatır ([[dark]]I was bored[[/dark]] = ben sıkıldım)."}, {"type": "text", "text": "Özne bir İNSAN ve bir duygudan bahsediliyorsa çoğunlukla [[amber]]-ed[[/amber]], özne bir ŞEY/DURUM/\"it\" ise çoğunlukla [[amber]]-ing[[/amber]] doğru olur."}, {"type": "example_check", "correct": "the documentary was fascinating", "wrong_note": "\"fascinated\" yanlıştır çünkü belgesel bir duygu hissetmez, duyguyu yaratan odur"}]}, {"heading": "Sıfat Sıralaması", "badge": "Sıralama Kuralı", "body": [{"type": "text", "text": "Birden fazla sıfat art arda sıralanırken genel sıra şudur: [[q]]görüş/yorum[[/q]] (beautiful) → [[q]]boyut[[/q]] (small) → [[q]]yaş[[/q]] (old) → [[q]]şekil[[/q]] → [[q]]renk[[/q]] → [[q]]köken[[/q]] (Italian) → [[q]]malzeme[[/q]] (wooden) → [[q]]amaç[[/q]]."}, {"type": "example_check", "correct": "a beautiful antique French wooden chair", "wrong_note": "\"a wooden antique French beautiful chair\" gibi sırayı tersine çevirmek YDS'de doğal/doğru kabul edilmez"}]}], "examples": [{"sentence": "The documentary about climate change was so fascinating that nobody in the room could look away.", "answer_word": "fascinating", "reasoning": "Özne [[b]]\"the documentary\"[[/b]] (bir şey, duyguyu yaratan kaynak) olduğu için doğru cevap [[right]]\"fascinating\"[[/right]]'tir; [[wrong]]\"fascinated\"[[/wrong]] yanlıştır çünkü belgesel bir duygu hissetmez, duyguyu yaratan odur."}, {"sentence": "A beautiful round antique wooden table stood in the corner of the room.", "answer_word": "A beautiful round antique wooden table", "reasoning": "Doğru sıfat sırası şekil-yaş-malzeme sırasıyla [[right]]\"A beautiful round antique wooden table\"[[/right]] gibi bir dizilimdir; sıfatların yerini değiştirip [[wrong]]\"A wooden antique round table\"[[/wrong]] demek İngilizce'de doğal kabul edilmeyen bir sıralamadır."}, {"sentence": "After hearing the shocking news about the merger, all the employees felt completely shocked about their job security.", "answer_word": "shocking", "reasoning": "\"news\" duyguyu YARATAN kaynak olduğu için -ing hali ([[right]]\"shocking\"[[/right]]) doğru olur; \"employees\" ise bu haberden ETKİLENEN kişiler olduğu için -ed hali ([[right]]\"shocked\"[[/right]]) doğru olur."}, {"sentence": "A beautiful antique French wooden chair had been in the family for three generations before it was finally restored.", "answer_word": "A beautiful antique French wooden chair", "reasoning": "Doğru sıralama görüş (beautiful) → yaş (antique) → köken (French) → malzeme (wooden) şeklindedir, yani doğru cevap [[right]]\"A beautiful antique French wooden\"[[/right]] dizilimidir; malzemeyi en başa alıp [[wrong]]\"A wooden antique French beautiful chair\"[[/wrong]] demek İngilizcede doğal kabul edilmeyen bir sıralama oluşturur."}]}$tagbd$::jsonb WHERE id = '816a2d8f-fdde-4816-affe-633fddb74d56';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Önce kaç şeyden bahsedildiğine bak: TAM OLARAK İKİ şey varsa [[q]]both/either/neither[[/q]], İKİDEN FAZLA şey varsa [[q]]all[[/q]] kullanılır.", "items": [{"heading": "İki mi, İkiden Fazla mı?", "body": [{"type": "text", "text": "[[ok]]both[[/ok]]: TAM OLARAK İKİ şey/kişi, ikisi de (olumlu)."}, {"type": "text", "text": "[[ok]]either[[/ok]]: TAM OLARAK İKİ şey/kişi, ikisinden biri — genelde soru/olumsuzlukla birlikte [[q]]not...either[[/q]]."}, {"type": "text", "text": "[[ok]]neither[[/ok]]: TAM OLARAK İKİ şey/kişi, ikisinden hiçbiri — kendi içinde olumsuzluk taşır, ayrıca \"not\" eklenmez."}, {"type": "text", "text": "[[ok]]all[[/ok]]: İKİDEN FAZLA şey/kişi."}]}, {"heading": "\"of\" ile Kullanım", "body": [{"type": "text", "text": "[[q]]both of / either of / neither of / all of[[/q]] ile kullanıldıklarında ardından belirli bir isim grubu (the, these, my gibi belirteçli) veya zamir gelir."}]}, {"heading": "Özne-Yüklem Uyumu", "body": [{"type": "text", "text": "[[q]]neither/either + tekil isim[[/q]] tekil fiil alır ([[dark]]Neither answer is correct[[/dark]]), [[q]]both/all + çoğul isim[[/q]] çoğul fiil alır."}, {"type": "example_check", "correct": "Neither answer is correct", "wrong_note": "\"neither\" tekil isimle birlikte tekil fiil ister, çoğul fiille kullanılamaz"}]}], "examples": [{"sentence": "All of the three candidates performed exceptionally well in the interview.", "answer_word": "All", "reasoning": "Üç adaydan bahsedildiği (ikiden fazla) için doğru cevap [[right]]\"All\"[[/right]]'dır; [[wrong]]\"both\"[[/wrong]] burada yanlıştır çünkü \"both\" sadece tam olarak iki şey için kullanılabilir."}, {"sentence": "Both of the two methods works efficiently, so you can choose whichever you prefer.", "answer_word": "Both", "reasoning": "İki yöntemden bahsediliyor ve ikisinin de işe yaradığı olumlu bir şekilde anlatılıyor → doğru cevap [[right]]\"Both\"[[/right]]'tur (çoğul fiil [[q]]\"work\"[[/q]] de kullanılabilir); [[wrong]]\"Neither\"[[/wrong]] burada yanlıştır çünkü \"neither\" olumsuz bir anlam taşır (hiçbiri işe yaramaz demektir), cümledeki anlamla çelişir."}, {"sentence": "Neither of my two brothers is interested in sports; they both prefer reading.", "answer_word": "Neither", "reasoning": "İki kardeşten bahsediliyor ve HİÇBİRİNİN spor ile ilgilenmediği (olumsuz bir durum) anlatılıyor → doğru cevap [[right]]\"Neither\"[[/right]]'dır (tekil fiil [[q]]\"is\"[[/q]] ile uyumlu); [[wrong]]\"either\"[[/wrong]] tek başına bu olumsuz anlamı taşıyamaz, \"not... either\" şeklinde kullanılması gerekirdi."}, {"sentence": "You can park on either side of the street; parking is free on both this week.", "answer_word": "either", "reasoning": "İki taraftan bahsediliyor ve HERHANGİ BİRİNİN seçilebileceği anlatılıyor → doğru cevap [[right]]\"either\"[[/right]]'dir; [[wrong]]\"all\"[[/wrong]] burada yanlıştır çünkü \"all\" ikiden fazla seçenek için kullanılır, sadece iki taraf söz konusuyken uygun değildir."}]}$tagbd$::jsonb WHERE id = '51723fdd-1abf-48dc-b539-15d55f1adae7';
